const matches = ALL_TOOLS.filter(x => /group|feed|post|message/i.test(x.name+" "+x.description));
text(matches);
const r = await Promise.allSettled([
  tools.exec_command({cmd:"ls -la && rg --files",workdir:"/workspace",max_output_tokens:3000}),
  tools.exec_command({cmd:"/opt/reference/executable --help",workdir:"/tmp",max_output_tokens:3000})
]);
for (const x of r) text(x.status==="fulfilled"?x.value.output:x.reason);

