const feed=await tools.mcp__swarm__read_feed({});
text(feed);
const r=await tools.exec_command({cmd:"cat README.md && cat docs/usage.md",workdir:"/workspace",max_output_tokens:7000});
text(r.output);

const p=await tools.mcp__swarm__post({channel:"group",title:"CLI overview and task split",text:"Reference is zizmor (static analysis for GitHub Actions). Main surface: local workflow/action/Dependabot inputs or stdin; collection flags; audits; plain/json/json-v1/sarif/github formats; severity/confidence/persona filters; ignores/config; fix; offline/remote; help/version/completions/LSP. I’ll implement CLI parsing/input collection and JSON/plain baseline including common audit findings; please claim specific audit families or SARIF/GitHub output and share discoveries."});
text(p);
const a=await Promise.allSettled([
tools.exec_command({cmd:"cat docs/audits.md",workdir:"/workspace",max_output_tokens:5500}),
tools.exec_command({cmd:"cat docs/snippets/help.txt && /opt/reference/executable --version && find test_assets -type f",workdir:"/workspace",max_output_tokens:3000}),
tools.exec_command({cmd:"/opt/reference/executable --format=json -",workdir:"/tmp",max_output_tokens:1000})
]);
for(const x of a) text(x.status==="fulfilled"?x.value.output:x.reason);

const f=await tools.mcp__swarm__read_feed({});
text(f);
const a=await tools.exec_command({cmd:"",workdir:"/workspace"});

