"""Small offline source detector for template injection in Actions run blocks."""
import re


_EXPR = re.compile(r"\$\{\{\s*(.*?)\s*\}\}")
_KNOWN_SAFE = {
    "github.sha", "github.workflow", "github.workflow_ref",
    "github.workflow_sha", "github.run_id", "github.run_number",
    "github.run_attempt", "github.repository", "github.repository_id",
    "github.repository_owner", "github.repository_owner_id",
}


def detect_template_injection(text, persona="regular"):
    """Return ``(line_number, expression)`` for suspicious expansions in run blocks.

    The scanner deliberately works on source lines so callers can attach the
    result to their YAML location representation.  Line numbers are 1-based.
    """
    lines = text.splitlines()
    hits = []
    in_run = False
    run_indent = -1
    content_indent = None
    for i, line in enumerate(lines):
        stripped = line.lstrip()
        indent = len(line) - len(stripped)
        if in_run and stripped and not stripped.startswith("#"):
            if content_indent is None and indent > run_indent:
                content_indent = indent
            elif content_indent is not None and indent < content_indent:
                in_run = False
                content_indent = None
        m = re.match(r"^\s*(?:-\s*)?run\s*:\s*(.*)$", line)
        if m:
            value = m.group(1)
            run_indent = indent
            in_run = value.strip() in ("", "|", ">", "|-", ">-") or value.strip().startswith(("|", ">"))
            content_indent = None
            # Inline scalars and the first content line of block scalars.
            for expr in _EXPR.finditer(value):
                if _suspicious(expr.group(1), persona):
                    hits.append((i + 1, expr.group(1)))
            continue
        if in_run:
            for expr in _EXPR.finditer(line):
                if _suspicious(expr.group(1), persona):
                    hits.append((i + 1, expr.group(1)))
    return hits


def _suspicious(expression, persona):
    expr = expression.strip()
    if persona in ("auditor", "pedantic"):
        return True
    # Regular mode permits values that are generated by the workflow engine
    # and are not controlled by a triggering user.
    return not (expr in _KNOWN_SAFE or expr.startswith("github.sha "))
"""Detect block-scalar ``if`` values with fenced expressions and trailing LF."""
import re


def detect_unsound_condition(text):
    """Return 1-based line numbers for suspect ``if: |`` / ``if: >`` fields."""
    lines = text.splitlines()
    results = []
    for i, line in enumerate(lines):
        m = re.match(r"^(\s*)if\s*:\s*([|>])([+-]?)(?:\s*(?:#.*)?)$", line)
        if not m or "-" in m.group(3):
            continue
        base = len(m.group(1))
        for j in range(i + 1, len(lines)):
            candidate = lines[j]
            if not candidate.strip():
                continue
            indent = len(candidate) - len(candidate.lstrip())
            if indent <= base:
                break
            if "${{" in candidate and "}}" in candidate:
                results.append((i + 1, j + 1))
                break
    return results

