    order={'informational':0,'low':1,'medium':2,'high':3}; conf={'low':0,'medium':1,'high':2}
    findings=[f for f in findings if order.get(f['determinations']['severity'].lower(),0)>=order.get(a.min_severity,0) and conf.get(f['determinations']['confidence'].lower(),0)>=conf.get(a.min_confidence,0)]
    audit_order={'unsound-contains':-1,'artipacked':0,'excessive-permissions':1,'dangerous-triggers':2,'bot-conditions':3,
                 'template-injection':4,'unpinned-uses':5,'unsound-condition':6,
                 'self-hosted-runner':7,'anonymous-definition':8,'concurrency-limits':9}
    findings.sort(key=lambda f:audit_order.get(f.get('ident'),100))
